import{_ as t,o as a,c as r,a6 as s}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse('{"title":"Glossary","description":"Every word the Piwi docs and dashboard use for Playwright results: run, test case, execution, failure cluster, baseline, live runs, analytics, the Test Map and its gaps.","frontmatter":{"title":"Glossary","description":"Every word the Piwi docs and dashboard use for Playwright results: run, test case, execution, failure cluster, baseline, live runs, analytics, the Test Map and its gaps.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/concepts.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/concepts.html"}],["meta",{"property":"og:title","content":"Glossary | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Every word the Piwi docs and dashboard use for Playwright results: run, test case, execution, failure cluster, baseline, live runs, analytics, the Test Map and its gaps."}]]},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md","lastUpdated":1794759890000}'),o={name:"guide/concepts.md"};function n(i,e,h,l,d,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><p>Every word the documentation and the dashboard use, each defined in a few lines with a link to the page that holds its rule. A word that names two things elsewhere keeps one meaning here, and <a href="#words-kept-to-one-meaning">Words kept to one meaning</a> names the others. New to Piwi? <a href="./core-concepts.html">Core concepts</a> reads the dozen words a first run meets, with the object model.</p><h2 id="the-object-model" tabindex="-1">The object model <a class="header-anchor" href="#the-object-model" aria-label="Permalink to &quot;The object model&quot;">​</a></h2><p>How projects, test runs, test cases, executions and failure clusters hold each other: <a href="./core-concepts.html#the-object-model">Core concepts</a>.</p><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><h3 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h3><p>A named container for one suite&#39;s results, usually one repository or one suite within it. A project is created the first time results arrive under a new <code>projectName</code>, and carries its own tags, <a href="#role-and-group">role grants</a>, source control connection, default branch, capability decisions and AI-diagnosis instructions; retention is set for the whole instance (<a href="/operate/storage.html">Storage &amp; retention</a>). Its <strong>status</strong> is the outcome of its latest run, or of its <a href="/features/branches.html#the-project-status">status filter</a>&#39;s.</p><h3 id="test-run" tabindex="-1">Test run <a class="header-anchor" href="#test-run" aria-label="Permalink to &quot;Test run&quot;">​</a></h3><p>Everything one <code>npx playwright test</code> invocation produced: counts, duration, the HTML report, CI and git metadata, and its <a href="#execution">executions</a>. One CI pipeline&#39;s shards make one run (<a href="./ci.html#sharding">Sharding</a>), and a run fills in while it goes (<a href="./reporter.html#live-streaming">Live streaming</a>). A run <strong>ran to its end</strong> when it passed, failed or hit the global timeout; only such runs count in <a href="/reference/test-metadata.html#how-a-result-counts">a project&#39;s health</a>. A <strong>requested run</strong> is one a person asked for from the dashboard and ran on their own machine (<a href="/features/run-on-my-machine.html#a-requested-run-is-yours-alone">Run on my machine</a>).</p><h3 id="test-case" tabindex="-1">Test case <a class="header-anchor" href="#test-case" aria-label="Permalink to &quot;Test case&quot;">​</a></h3><p>The <strong>identity of a test across time</strong>: its project, file, <code>describe</code> path and title. It is created and reused as results arrive, never submitted, so renaming a test or moving its file makes a new one (<a href="/reference/test-metadata.html#external-test-ids">External test IDs</a>). It is browser-independent: <code>login.spec.ts › signs in</code> is one test case on every browser of your matrix. &quot;This test is flaky&quot; is a statement about a test case. What a <strong>run</strong> of a test is on its pages: <a href="/reference/test-metadata.html#how-a-result-counts">How a result counts</a>.</p><h3 id="execution" tabindex="-1">Execution <a class="header-anchor" href="#execution" aria-label="Permalink to &quot;Execution&quot;">​</a></h3><p><strong>One attempt of one test case, in one run, on one browser</strong>: the error, steps, trace, screenshots and the diagnosis of one failure. A retry is an execution of its own, and so is each <code>--repeat-each</code> repetition. The docs also call it a <em>test-run case</em>. &quot;Here is the stack trace&quot; is a statement about an execution. When a test counts as flaky, failed or <strong>interrupted</strong> in a run, and how every view reads it: <a href="/reference/test-metadata.html#how-a-result-counts">How a result counts</a>.</p><h3 id="pass-rate" tabindex="-1">Pass rate <a class="header-anchor" href="#pass-rate" aria-label="Permalink to &quot;Pass rate&quot;">​</a></h3><p><strong>The share of a test&#39;s, a run&#39;s or a project&#39;s results that passed</strong>, counted over the results that passed or failed, so skipped tests do not lower it. Every view computes it by one rule, and shows a dash rather than a number when nothing passed or failed: <a href="/reference/test-metadata.html#how-a-result-counts">How a result counts</a>.</p><h3 id="flaky-rate" tabindex="-1">Flaky rate <a class="header-anchor" href="#flaky-rate" aria-label="Permalink to &quot;Flaky rate&quot;">​</a></h3><p><strong>The share of a test&#39;s runs that passed only on a retry</strong>, over the same runs the <a href="#pass-rate">pass rate</a> counts. A file&#39;s or a directory&#39;s flaky rate reads its tests&#39; runs the same way. The <a href="#flakiness-score">flakiness score</a> and Flake Lab&#39;s rate are other numbers: <a href="/reference/test-metadata.html#how-a-result-counts">How a result counts</a>.</p><h3 id="baseline-last-green-run" tabindex="-1">Baseline (last green run) <a class="header-anchor" href="#baseline-last-green-run" aria-label="Permalink to &quot;Baseline (last green run)&quot;">​</a></h3><p><strong>The earlier run a run is compared with</strong> to answer &quot;what changed?&quot;: by default the same project&#39;s most recent passing run, chosen by environment first, then branch. The Changes tab, the regression signals, the CI gate, pull-request feedback and the AI diagnosis all read it, and so do the environment, visual and page diffs of one failing execution. Which run it is, and what happens when none passed: <a href="/features/run-changes.html#the-baseline">The baseline</a>. The default and base branches it falls back to: <a href="/features/branches.html">Branches</a>.</p><h3 id="new-regression-newly-flaky" tabindex="-1">New regression, newly flaky <a class="header-anchor" href="#new-regression-newly-flaky" aria-label="Permalink to &quot;New regression, newly flaky&quot;">​</a></h3><p><strong>What a test did differently from the <a href="#baseline-last-green-run">baseline</a></strong>: a <strong>new regression</strong> fails here and passed there; a <strong>newly flaky</strong> test passed here only on a retry and passed at its first attempt there. Both name a change between two runs, not its cause: a newly flaky test can be your change or an old flake. How to tell: <a href="/features/run-changes.html#what-newly-flaky-says-about-your-change">What newly flaky says about your change</a>.</p><h3 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h3><p>A free-text label on a run (<code>production</code>, <code>staging</code>, a preview URL, whatever you use), set with the reporter&#39;s <code>environment</code> option or <code>PIWI_ENVIRONMENT</code>. It is a <strong>scoping</strong> dimension, not a configuration one: flaky analysis, analytics and timeline markers can be narrowed to one environment, so a staging suite&#39;s noise doesn&#39;t blend into production&#39;s numbers.</p><h3 id="environment-incident" tabindex="-1">Environment incident <a class="header-anchor" href="#environment-incident" aria-label="Permalink to &quot;Environment incident&quot;">​</a></h3><p>A <strong>test run</strong> whose failures come from the environment under test being down or broken (staging refusing connections, a host that does not resolve), not from the tests or the code. Piwi flags it when the run finishes, or a person marks it, and leaves it out of the analysis that would blame the tests: see <a href="/features/environment-incidents.html#what-a-flagged-run-changes">What a flagged run changes</a>.</p><h3 id="tags-ownership" tabindex="-1">Tags &amp; ownership <a class="header-anchor" href="#tags-ownership" aria-label="Permalink to &quot;Tags &amp; ownership&quot;">​</a></h3><p>Two ways to say what a test <em>is</em>, both declared in the spec file. <strong>Tags</strong> come from Playwright (<code>@smoke</code>); they slice the test catalog and the flaky leaderboard, and a <a href="/features/merge-gate.html">CI merge gate</a> rule can require one. <strong>Ownership metadata</strong> comes from <code>piwi:</code> annotations such as <code>piwi:owner</code>: who answers for the test, shown as badges and carried into pull-request feedback. A test with no owner annotation takes its owner from <code>CODEOWNERS</code>. Accepted values and the fallback: <a href="/reference/test-metadata.html#test-tags">Test metadata</a>.</p><h2 id="live-runs" tabindex="-1">Live runs <a class="header-anchor" href="#live-runs" aria-label="Permalink to &quot;Live runs&quot;">​</a></h2><p>The words every tool uses for a run while it goes (<a href="/features/watch-a-run.html">Follow a run</a>).</p><h3 id="run-number" tabindex="-1">Run number <a class="header-anchor" href="#run-number" aria-label="Permalink to &quot;Run number&quot;">​</a></h3><p><strong>A run&#39;s id on the instance it reports to, <code>#78</code>, and its page there.</strong> The reporter learns it as the run starts and tells it to the editor or the desktop app that follows the run, so every tool links the same page (<a href="/features/watch-a-run.html#the-run-s-number-and-page">The run&#39;s number and page</a>).</p><h3 id="run-name" tabindex="-1">Run name <a class="header-anchor" href="#run-name" aria-label="Permalink to &quot;Run name&quot;">​</a></h3><p><strong>The name a run carries before it has a number</strong> (<code>piwiRunRef</code> in its metadata): the one its launcher gave it, an editor&#39;s ref or a run request&#39;s id, else one Piwi makes up for a run outside CI. A CI run has none: its number names it. See <a href="/reference/test-metadata.html#run-origin">Test metadata</a>.</p><h3 id="worker" tabindex="-1">Worker <a class="header-anchor" href="#worker" aria-label="Permalink to &quot;Worker&quot;">​</a></h3><p><strong>One of the run&#39;s Playwright processes, named by its lane, <code>Worker 2</code>.</strong> A worker Playwright starts again after a failure takes the same lane (<a href="/reference/test-metadata.html#worker-lanes">Worker lanes</a>).</p><h3 id="stop" tabindex="-1">Stop <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;Stop&quot;">​</a></h3><p><strong>A test standing at a call, waiting to be answered:</strong> at a breakpoint, after a step, at a Pause, at <code>page.pause()</code>, or at a failure held for a look. Each tool names it by why it stopped, in the same words (<a href="/features/watch-a-run.html#where-a-test-stopped">Where a test stopped</a>). A test ended there is skipped (<a href="/features/end-the-test.html">End the test</a>). How the test timeout and the dashboard&#39;s durations treat the time paused: <a href="/features/slow-tests.html#time-paused-at-a-stop">Time paused at a stop</a>.</p><h3 id="ci-position" tabindex="-1">CI position <a class="header-anchor" href="#ci-position" aria-label="Permalink to &quot;CI position&quot;">​</a></h3><p><strong>The call a running test of a CI run is at, in your code:</strong> a plain, read-only mark at the end of its line in the editors. Never a stop: nothing waits there, and no tool answers it. Which CI runs the editor and Piwi Picker follow: <a href="/features/editor-ci-runs.html">A CI run of your branch</a>.</p><h3 id="hold-failures" tabindex="-1">Hold failures <a class="header-anchor" href="#hold-failures" aria-label="Permalink to &quot;Hold failures&quot;">​</a></h3><p><strong>Whether a failed test waits at its line for an answer, in one run.</strong> Off, a failure goes on at once, as without Piwi. Some runs start with it on, any tool that follows a run can turn it on or off, and a run nobody attends never holds a failure. Which runs, and what a held test keeps: <a href="/features/watch-a-run.html#hold-failures">Hold failures</a>.</p><h3 id="presence-driving-a-stop" tabindex="-1">Presence, driving a stop <a class="header-anchor" href="#presence-driving-a-stop" aria-label="Permalink to &quot;Presence, driving a stop&quot;">​</a></h3><p><strong>Who else is on a run, and who acts at its stop.</strong> Each tool says which others have the run open, who watches each worker&#39;s page, and who drives a stop. One tool drives a stop at a time, a person or an agent, and a person can take the stop from an agent. How a stop is taken and given back: <a href="/features/runs-window.html#who-drives-a-stop">Who drives a stop</a>.</p><h3 id="watch-share-live" tabindex="-1">Watch, Share live <a class="header-anchor" href="#watch-share-live" aria-label="Permalink to &quot;Watch, Share live&quot;">​</a></h3><p><strong>Watch</strong> shows a worker&#39;s page live, in your editor, Piwi Picker or the desktop app (<a href="/features/watch-running-test.html">Watch a local test</a>). <strong>Share live</strong> lets a teammate watch a run on your machine from its page on the team instance (<a href="/features/share-live.html">Share a local run live</a>), where a CI run is watched in the <a href="/features/live-view.html">live view</a>, every worker at once with <a href="/features/watch-all.html">Watch all</a>, and a running page read as a document with <a href="/features/live-inspect.html">Inspect</a>. What each sends and keeps is on those pages.</p><h3 id="trace-so-far" tabindex="-1">Trace so far <a class="header-anchor" href="#trace-so-far" aria-label="Permalink to &quot;Trace so far&quot;">​</a></h3><p><strong>A running test&#39;s trace up to now, opened in Playwright&#39;s trace viewer</strong> on the machine the run runs on, with <strong>Open the trace so far</strong>. The attempt must be traced. Where the button shows and what it needs: <a href="/features/watch-running-test.html#open-the-trace-so-far">Open the trace so far</a>; the desktop app&#39;s <strong>Inspect</strong>, which reads the same trace: <a href="/features/desktop-runs.html#watch">Desktop app runs</a>.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><p><strong>A test run several times without retries and without the breakpoints, to see how often it passes</strong> (<strong>Verify ×3</strong> in the editors). It says how many of its repetitions passed (<code>Passed 3 of 3</code>, <code>Failed 1 of 3</code>) and never holds a failure. How it counts and what it says: <a href="/features/editor-runs.html#when-your-run-ends">When your run ends</a>.</p><h2 id="failures" tabindex="-1">Failures <a class="header-anchor" href="#failures" aria-label="Permalink to &quot;Failures&quot;">​</a></h2><h3 id="error-fingerprint-failure-cluster" tabindex="-1">Error fingerprint &amp; failure cluster <a class="header-anchor" href="#error-fingerprint-failure-cluster" aria-label="Permalink to &quot;Error fingerprint &amp; failure cluster&quot;">​</a></h3><p>The <strong>error fingerprint</strong> is a hash of a failed execution&#39;s error with what changes from one occurrence to the next masked out: numbers, ids, URLs, timestamps, an assertion&#39;s values. Every failed execution sharing a fingerprint joins one <strong>failure cluster</strong>, so fifty red tests from one broken endpoint become one cluster you triage once, with a status (open / resolved / ignored) and a note. What is masked, and when clusters merge: <a href="/features/failure-clusters.html#how-failures-are-grouped">How failures are grouped</a>.</p><h3 id="story" tabindex="-1">Story <a class="header-anchor" href="#story" aria-label="Permalink to &quot;Story&quot;">​</a></h3><p>The <strong>one explanation</strong> a failure page leads with when several <a href="/features/evidence.html#clues">clues</a> (deterministic, rule-based findings) form a known combination: <em>&quot;the Pay button stayed disabled because POST /api/checkout/quote was still in flight&quot;</em>, at the strongest member&#39;s strength, with every clue folded under it. The combinations, and what leads instead: <a href="/reference/clues.html#stories">Clue rules</a>.</p><h3 id="situation" tabindex="-1">Situation <a class="header-anchor" href="#situation" aria-label="Permalink to &quot;Situation&quot;">​</a></h3><p>The <strong>context</strong> of a failing execution, on its page: since when it has been failing and whether a newer execution failed again or passed, then the cluster it joins, its status and its issue. It also reads, condensed, in <a href="/features/notifications.html">alerts</a>. Each line: <a href="./first-failure.html">Your first failure, explained</a>.</p><h3 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h3><p>The <strong>one recommended action</strong> a failure page leads with, chosen by a policy rather than offered as a menu: apply a diagnosed patch, replace a broken locator, reproduce locally, re-run in CI, mark a cluster resolved. Every other action lives in the toolbox. The policy and its order: <a href="/features/fix-plans.html#the-next-step">Fix plans</a>.</p><h3 id="cluster-state" tabindex="-1">Cluster state <a class="header-anchor" href="#cluster-state" aria-label="Permalink to &quot;Cluster state&quot;">​</a></h3><p>Where a <strong>failure cluster</strong> stands, in one sentence with one verb next to a colored dot (<em>still failing</em>, <em>stopped failing</em>, <em>regressed</em>, …). It reconciles the human triage status with what the runs show, and offers the action that closes a gap between them. Every state and which runs count: <a href="/features/failure-clusters.html#the-state-line">The state line</a>.</p><h3 id="flakiness-score" tabindex="-1">Flakiness score <a class="header-anchor" href="#flakiness-score" aria-label="Permalink to &quot;Flakiness score&quot;">​</a></h3><p>A test case&#39;s <strong>score</strong> from how often it passed only on a retry and how often its status flips across runs, with a <strong>root-cause class</strong> and an <strong>impact ranking</strong> by the CI time it wastes. It is a property of the test case, computed over its history, so a test needs a few runs before it can be called flaky. The weights and the classes: <a href="/features/flaky-tests.html#flaky-test-detection">Flaky tests</a>.</p><h3 id="flake-experiment" tabindex="-1">Flake experiment <a class="header-anchor" href="#flake-experiment" aria-label="Permalink to &quot;Flake experiment&quot;">​</a></h3><p>A <code>piwi flake</code> session on one flaky test: a <strong>control arm</strong> with no condition, then one <strong>arm</strong> per suspect, each applying the suspect&#39;s condition (a delayed route, another test alongside) with retries off. An arm <strong>reproduced</strong> the flake when it fails, with the test&#39;s own error, significantly more often than the control; a <strong>verify</strong> experiment reruns that arm after a fix. The verdicts: <a href="/features/flake-lab.html#reading-the-verdict">Flake Lab</a>.</p><h3 id="fix-attempt" tabindex="-1">Fix attempt <a class="header-anchor" href="#fix-attempt" aria-label="Permalink to &quot;Fix attempt&quot;">​</a></h3><p>A change a person or an agent reports having made to fix a failure cluster (a patch, a locator edit, a fix plan carried out), on a commit or a branch. It is recorded <strong>applied</strong>, then <strong>verified</strong> when the cluster&#39;s tests pass on a run that carries it, or <strong>regressed</strong> when the cluster fails again. See <a href="/features/agent-skills.html#what-agents-report-back">Agent skills</a>.</p><h3 id="locator-snapshot" tabindex="-1">Locator snapshot <a class="header-anchor" href="#locator-snapshot" aria-label="Permalink to &quot;Locator snapshot&quot;">​</a></h3><p>What an element looked like when a locator call on it succeeded (role, accessible name, test id, structural anchors), recorded by the <a href="./capture-fixtures.html">capture fixtures</a> and keyed by the <strong>call site</strong> (<code>file:line</code>) rather than the selector text. When that locator later fails, its snapshots are what Piwi ranks replacement locators from. See <a href="/features/locator-healing.html#what-it-does">Locator healing</a>.</p><h2 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h2><h3 id="metric-dashboard-and-quality-report" tabindex="-1">Metric, dashboard and quality report <a class="header-anchor" href="#metric-dashboard-and-quality-report" aria-label="Permalink to &quot;Metric, dashboard and quality report&quot;">​</a></h3><p>A <strong>metric</strong> is a named number with one definition every surface reads (<a href="/features/analytics.html">Analytics</a>). An <strong>analytics dashboard</strong> is a named arrangement of widgets with a default scope (<a href="/features/dashboards.html">Dashboards</a>); <em>the dashboard</em> alone means the Piwi web app. A <strong>quality report</strong> is an analytics dashboard rendered as a document, not the run&#39;s Playwright <strong>run report</strong>; a <strong>report schedule</strong> sends it on a cadence, and each one sent is kept as a <strong>report snapshot</strong> (<a href="/features/quality-reports.html">Quality reports</a>).</p><h2 id="test-map" tabindex="-1">Test Map <a class="header-anchor" href="#test-map" aria-label="Permalink to &quot;Test Map&quot;">​</a></h2><p>The <strong>Test Map</strong> is one graph per project of what the application exposes (pages, controls, links, routes, the handlers and dependencies behind them) and which tests reach each of them. See <a href="/features/scenario-gaps.html">Scenario gaps &amp; the Test Map</a>.</p><h3 id="reach" tabindex="-1">Reach <a class="header-anchor" href="#reach" aria-label="Permalink to &quot;Reach&quot;">​</a></h3><p>A test <strong>reaches</strong> a route, a page, a control or a link when a run observes it doing so: a request to the route, a locator call on the page, a locator that names the control. Triage can record reach too. The route and page gaps are read from observed reach; the code detectors read coverage. Only a trusted test&#39;s reach counts in full. The rules: <a href="/reference/gap-detectors.html#detectors">Gap detectors &amp; exposure</a>.</p><h3 id="feature-and-hub" tabindex="-1">Feature and hub <a class="header-anchor" href="#feature-and-hub" aria-label="Permalink to &quot;Feature and hub&quot;">​</a></h3><p>A <strong>feature</strong> is a product area named by the <a href="/reference/test-metadata.html"><code>piwi:feature</code> tag</a> on tests. It groups what those tests reach, and what they miss nearby. A <strong>hub</strong> is a node most tests reach, such as a session route: it belongs to no one feature. See <a href="/reference/gap-detectors.html#features">how features group</a>.</p><h3 id="code-reach" tabindex="-1">Code reach <a class="header-anchor" href="#code-reach" aria-label="Permalink to &quot;Code reach&quot;">​</a></h3><p>The application source files a test executed, in the page from Chromium&#39;s JavaScript coverage with <a href="/features/code-reach.html">code reach</a> on, in the backend with <a href="/features/server-coverage.html">server coverage</a> on: observed reach at file level, never line coverage. It feeds <a href="/features/change-impact.html">impact-from-diff</a> and <a href="/features/uncovered-changes.html">Uncovered changes</a>.</p><h3 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage&quot;">​</a></h3><p>Which source code a test ran, per file and <strong>runtime</strong> (<code>browser</code> or <code>server</code>), at a <strong>granularity</strong>: the files only, the functions that ran, or the executed lines too. <a href="#code-reach">Code reach</a> is its file-level view. A test&#39;s coverage is <strong>incomplete</strong> when part of it could not be collected. The granularities and their cost: <a href="/reference/coverage-cost.html">Coverage cost</a>.</p><h3 id="coverage-report-and-suite" tabindex="-1">Coverage report and suite <a class="header-anchor" href="#coverage-report-and-suite" aria-label="Permalink to &quot;Coverage report and suite&quot;">​</a></h3><p>A <strong>coverage report</strong> is one tool&#39;s coverage of one suite&#39;s whole run at one commit, attributed to no test. A <strong>suite</strong> is the tests a report comes from, named when uploading (<code>unit-back</code>), of kind <code>unit</code> or <code>e2e</code>; not Playwright&#39;s <code>describe</code> block. The <strong>coverage scope</strong> decides which files a project&#39;s coverage counts. See <a href="/features/combined-coverage.html">Combined coverage</a>.</p><h3 id="coverage-and-the-test-map" tabindex="-1">Coverage and the Test Map <a class="header-anchor" href="#coverage-and-the-test-map" aria-label="Permalink to &quot;Coverage and the Test Map&quot;">​</a></h3><p>Two answers to &quot;what do the tests miss&quot;. <strong>Coverage</strong> measures the code: which lines and functions ran, as a ratio; the lines no test or suite ran are <strong>lines not run</strong>. The <strong>Test Map</strong> measures the application: which routes, pages and controls the tests reach; what they miss becomes a <a href="#scenario-gap">scenario gap</a>, never a percentage. They meet on the project&#39;s <a href="/features/scenario-gaps.html#the-coverage-tab">Coverage tab</a> and on a <a href="/features/code-reach.html#which-tests-run-a-file">file&#39;s coverage page</a>.</p><h3 id="uncovered-change" tabindex="-1">Uncovered change <a class="header-anchor" href="#uncovered-change" aria-label="Permalink to &quot;Uncovered change&quot;">​</a></h3><p>A changed file of a pull request that no test reached and no suite ran a changed line of. One rule decides it for the pull-request comment, the gate, MCP and the <em>changed, unreached</em> gap. <strong>Patch coverage</strong> is the same question by line: the share of the changed lines that ran. See <a href="/features/uncovered-changes.html#one-rule-for-every-changed-file">Uncovered changes</a>.</p><h3 id="reusable-result" tabindex="-1">Reusable result <a class="header-anchor" href="#reusable-result" aria-label="Permalink to &quot;Reusable result&quot;">​</a></h3><p>A test result whose code had already passed unchanged: an earlier pass of the same test ran the same file versions, so the run could have kept that pass instead. A reusable result that failed came from the test, its data or its environment. See <a href="/features/reuse-forecast.html#what-counts-as-reusable">Reuse forecast</a>.</p><h3 id="suspect-lines" tabindex="-1">Suspect lines <a class="header-anchor" href="#suspect-lines" aria-label="Permalink to &quot;Suspect lines&quot;">​</a></h3><p>The lines changed since a failing test&#39;s last passing run that the failing tests executed, read from their <a href="#coverage">coverage</a>, ranked by how few passing tests executed them too. The failure pages, the cluster&#39;s diff, the AI diagnosis and the fix plan name them. How they are ranked: <a href="/features/server-coverage.html#suspect-lines">Suspect lines</a>.</p><h3 id="locator-index" tabindex="-1">Locator index <a class="header-anchor" href="#locator-index" aria-label="Permalink to &quot;Locator index&quot;">​</a></h3><p>The locator chains each test used in its steps, recorded per branch and per Playwright project. It answers which tests use a locator, and it feeds <a href="/features/locator-usage.html">Who uses a locator</a> and <a href="/features/tested-elements.html">Tested elements</a>.</p><h3 id="locator-break" tabindex="-1">Locator break <a class="header-anchor" href="#locator-break" aria-label="Permalink to &quot;Locator break&quot;">​</a></h3><p>A locator of the index that a change stops matching: the diff removes or renames a string one of its calls finds the element by. <a href="/features/preflight.html">Locator preflight</a> lists them, <em>likely</em> or <em>possible</em>.</p><h3 id="page-key" tabindex="-1">Page key <a class="header-anchor" href="#page-key" aria-label="Permalink to &quot;Page key&quot;">​</a></h3><p>A page&#39;s URL reduced to its path pattern, ids replaced by placeholders: <code>/orders/123?tab=items</code> and <code>/orders/456</code> are both <code>/orders/:id</code>, on staging and in production alike. The Test Map&#39;s page nodes, the page each locator was used on and Piwi Picker&#39;s <strong>This page</strong> all use it. The rules: <a href="/reference/gap-detectors.html#what-the-graph-includes">What the graph includes</a>; Piwi Picker&#39;s path prefixes: <a href="/features/extension-connection.html#url-patterns">URL patterns</a>.</p><h3 id="brittle-locator" tabindex="-1">Brittle locator <a class="header-anchor" href="#brittle-locator" aria-label="Permalink to &quot;Brittle locator&quot;">​</a></h3><p>A locator a test uses that breaks on a change unrelated to what the test checks: a position, a styling class, the document structure, a generated id. Piwi judges each locator of the index <em>brittle</em>, <em>watch</em> or <em>stable</em>; see <a href="/reference/locator-stability.html">Locator stability rules</a>. Not to be confused with the <em>fragile</em><a href="#gap-class">gap class</a>, which is about the tests reaching a node, not a locator.</p><h3 id="scenario-gap" tabindex="-1">Scenario gap <a class="header-anchor" href="#scenario-gap" aria-label="Permalink to &quot;Scenario gap&quot;">​</a></h3><p>A test the suite does not have yet, proposed from the Test Map with its evidence and a next step: a route no test reaches, a control nobody exercises, a changed file no test reaches. A gap is triaged like a failure cluster: accept it, snooze it, dismiss it with a reason, or mark it covered by an existing test (<a href="/features/scenario-gaps.html#triage">Triage</a>).</p><h3 id="gap-class" tabindex="-1">Gap class <a class="header-anchor" href="#gap-class" aria-label="Permalink to &quot;Gap class&quot;">​</a></h3><p>How serious a gap is: <strong>blind-spot</strong> (nothing exercises it), <strong>false-comfort</strong> (the tests pass without checking it) or <strong>fragile</strong> (what reaches it could stop at any time). Server probes report <strong>findings</strong> instead, <strong>unhandled</strong> or <strong>degraded</strong>. What each class covers: <a href="/reference/gap-detectors.html#detectors">Detectors</a>.</p><h3 id="detector" tabindex="-1">Detector <a class="header-anchor" href="#detector" aria-label="Permalink to &quot;Detector&quot;">​</a></h3><p>A rule that reads the Test Map and the run history and reports one kind of gap, such as <em>declared, never hit</em> or <em>single covering test</em>. Each gap names the detector that raised it; <a href="/reference/gap-detectors.html">Gap detectors &amp; exposure</a> lists them all.</p><h3 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h3><p>How much a gap&#39;s node matters, from how often its files change and for how long, whether they were part of an earlier escaped failure, and the priority of the tests that reach it. A gap&#39;s score, which ranks it, is its exposure times the detector&#39;s confidence. The factors: <a href="/reference/gap-detectors.html#exposure">Exposure</a>.</p><h3 id="probe" tabindex="-1">Probe <a class="header-anchor" href="#probe" aria-label="Permalink to &quot;Probe&quot;">​</a></h3><p>A re-run of a passing test with one injected fault (a 500, an empty body, a dropped field, a slow response), recording whether the test noticed. A client probe injects the fault at the Playwright boundary; a server probe asks the <a href="./backend-logs.html#server-probes">backend instrumentation</a> to inject it inside the server. A <strong>probe run</strong> is marked as one (<a href="/features/probes.html#what-a-probe-run-never-counts">What a probe run never counts</a>).</p><h3 id="declared-surface" tabindex="-1">Declared surface <a class="header-anchor" href="#declared-surface" aria-label="Permalink to &quot;Declared surface&quot;">​</a></h3><p>The routes and pages the application says it has, from the instrumentation&#39;s route manifest, a committed <code>piwi.manifest.json</code> or an OpenAPI document, as opposed to the ones tests reached. A declared route nothing reaches is a <em>declared, never hit</em> gap (<a href="/features/scenario-gaps.html#declared-surface">Declared surface</a>).</p><h3 id="page-inventory" tabindex="-1">Page inventory <a class="header-anchor" href="#page-inventory" aria-label="Permalink to &quot;Page inventory&quot;">​</a></h3><p>The controls (role and accessible name) and links the reporter records on the pages a passing run visits, so the Test Map knows what a page offers beyond what the tests clicked. Off by default: turn it on with <code>capturePageInventory</code>. What it reads and keeps: <a href="/reference/gap-detectors.html#what-the-graph-includes">What the graph includes</a>.</p><h3 id="map-health" tabindex="-1">Map health <a class="header-anchor" href="#map-health" aria-label="Permalink to &quot;Map health&quot;">​</a></h3><p>How complete a project&#39;s Test Map is, per input (the page inventory, route handlers, probes, the declared surface, change history…), with the detectors each input wakes. A quiet Gaps view can mean a map that cannot see; the panel names the step behind each input that is short (<a href="/features/scenario-gaps.html#map-health">Map health</a>).</p><h3 id="url-pattern" tabindex="-1">URL pattern <a class="header-anchor" href="#url-pattern" aria-label="Permalink to &quot;URL pattern&quot;">​</a></h3><p>A glob over a page&#39;s whole address that ties the pages of a site to a project, with an optional environment and branch. Each project keeps its own list, and the browser extension reads them to know which project the page it is on belongs to. See <a href="/features/extension-connection.html#url-patterns">Extension connection</a>.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><h3 id="role-and-group" tabindex="-1">Role and group <a class="header-anchor" href="#role-and-group" aria-label="Permalink to &quot;Role and group&quot;">​</a></h3><p>With <a href="/operate/authentication.html">authentication</a> on, every account holds an <strong>instance role</strong>, <strong>Administrator</strong> or <strong>Member</strong>. A Member&#39;s rights in a project come from the <strong>project roles</strong> they hold there, granted on one project or on all of them. A <strong>group</strong> is a named set of users that receives project roles the way a user does. See <a href="/operate/project-access.html">Access, roles and groups</a>.</p><h2 id="words-kept-to-one-meaning" tabindex="-1">Words kept to one meaning <a class="header-anchor" href="#words-kept-to-one-meaning" aria-label="Permalink to &quot;Words kept to one meaning&quot;">​</a></h2><p>Some words name two things across the docs, the dashboard and the tools. Each keeps the meaning in the middle column on these pages; the others take the name on the right, or are told apart by the place they are in.</p><table tabindex="0"><thead><tr><th>Word</th><th>Means</th><th>The other senses</th></tr></thead><tbody><tr><td>stop</td><td>A test standing at a call (<a href="#stop">Stop</a>)</td><td><strong>Stop</strong>, in bold, is a button&#39;s label: it ends a run, a recording or an answer</td></tr><tr><td>share</td><td><strong>Share live</strong>: a teammate watches a run on your machine</td><td><strong>Share with Playwright tools</strong> binds a stopped test&#39;s browser for Playwright&#39;s tools; a <a href="/features/share-links.html">share link</a> is a signed read-only link</td></tr><tr><td>On your machine</td><td>A run on a developer&#39;s machine: the run page&#39;s card for a desktop run and the mark of a <a href="#test-run">requested run</a></td><td>none</td></tr><tr><td>run</td><td>A <a href="#test-run">test run</a></td><td>A test&#39;s result in a run is a <em>run of a test</em> (<a href="/reference/test-metadata.html#how-a-result-counts">How a result counts</a>); one of the times Flake Lab or a verification runs a test is a <em>repetition</em></td></tr><tr><td>environment</td><td>The label a run carries (<a href="#environment">Environment</a>)</td><td>The app a run tests is the <em>environment under test</em> (<a href="#environment-incident">incident</a>); the machine a run executed on is its <a href="/features/run-environment.html">run environment</a>; the flaky class <code>environment</code> means one browser, or one runner time zone or locale, fails</td></tr><tr><td>wasted</td><td><a href="/features/slow-tests.html#wasted-time">Wasted time</a>: waits plus failed attempts, as Analytics counts it</td><td>The flaky list&#39;s <em>wasted CI minutes</em> of one test are its retry passes times its average failed attempt</td></tr><tr><td>coverage, reach</td><td><a href="#coverage">Coverage</a>: the code a test ran; <a href="#reach">reach</a>: what a run observed a test touch</td><td><a href="#code-reach">Code reach</a> is coverage at file level; <em>Uncovered changes</em> and the <strong>Coverage</strong> tab keep their names</td></tr><tr><td>diverged</td><td>The dashboard&#39;s verdict for a replay that could not play a step</td><td>Piwi Picker says <em>Could not reach the bug</em> (<a href="/features/replay-a-bug-report.html">Replay a bug report</a>)</td></tr><tr><td>picker</td><td><strong>Piwi Picker</strong>, always with its name, is the browser extension</td><td>A tool that turns a click into locators is named by where it works: the dashboard&#39;s <em>snapshot picker</em> (<strong>Pick from snapshot</strong>, <strong>Open in picker</strong>), the trace viewer&#39;s <em>Pick locator</em>, the <em>failure-time picker</em> in a local run&#39;s browser</td></tr><tr><td>dashboard</td><td>The web app a Piwi instance serves</td><td>A saved set of Analytics widgets is an <a href="/features/dashboards.html">analytics dashboard</a>; a hosting provider&#39;s web console is its <em>console</em></td></tr><tr><td>report</td><td>Always with its kind</td><td><em>quality report</em>, <em>HTML report</em> of a run, <em>offline export</em>, <em>bug report</em>, Playwright&#39;s <em>blob report</em></td></tr><tr><td>test case</td><td>A test&#39;s identity across time (<a href="#test-case">Test case</a>)</td><td>One attempt of it is an <a href="#execution">execution</a></td></tr><tr><td>project</td><td>A Piwi <a href="#project">project</a>, named by the reporter&#39;s <code>projectName</code></td><td>A <em>Playwright project</em> (a <code>projects</code> entry of the config, whose name the <code>browser</code> field records) is always called so; the reader&#39;s code is their <em>repository</em></td></tr><tr><td>integration</td><td>A <em>backend integration</em>: an instrumentation package in the app under test (<a href="./backend-logs.html">Backend instrumentation</a>)</td><td><strong>Settings → Integrations</strong> holds the <em>connections</em> to <a href="/operate/integrations.html">Jira Cloud</a> and <a href="/operate/zephyr-scale.html">Zephyr Scale Cloud</a>; <strong>Integrations</strong> is also the group of a project&#39;s Settings that binds those connections and CI</td></tr><tr><td>baseline</td><td>The run a run is compared with (<a href="#baseline-last-green-run">Baseline</a>)</td><td>A visual snapshot, a pinned commit or a starting value is named by what it is</td></tr><tr><td>exposure</td><td>How much a gap&#39;s node matters (<a href="#exposure">Exposure</a>)</td><td>none</td></tr><tr><td>finding</td><td>Always with its kind: a <em>resilience finding</em> (the app did not cope with a server probe), a <em>leak finding</em></td><td>A <a href="/features/evidence.html#clues">clue</a> is a rule-based finding about one failure</td></tr><tr><td>verified</td><td>Always with its noun: <em>diagnosis verified</em>, <em>verified fixed</em>, a <em>verified</em> fix attempt, a <a href="#verification">verification</a></td><td>none</td></tr><tr><td>class</td><td>Always with its kind: the flaky <em>root-cause class</em>, the <a href="#gap-class">gap class</a></td><td>none</td></tr><tr><td>Performance, Timeline</td><td>A tab or a page, named by its place: <strong>Project → Performance</strong>, <strong>Settings → Performance</strong>, a run&#39;s <strong>Timeline</strong> tab</td><td><a href="/features/timeline-markers.html">Timeline markers</a> are the events drawn on the trend charts</td></tr></tbody></table><h2 id="where-each-concept-lives-in-the-ui" tabindex="-1">Where each concept lives in the UI <a class="header-anchor" href="#where-each-concept-lives-in-the-ui" aria-label="Permalink to &quot;Where each concept lives in the UI&quot;">​</a></h2><p>The page and URL of each object of the model: <a href="./core-concepts.html#where-each-concept-lives-in-the-ui">Core concepts</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./core-concepts.html">Core concepts</a> — the words a first run meets</li><li><a href="./getting-started.html">Getting started</a> — get results flowing in</li><li><a href="/features/ui-overview.html">UI overview</a> — a map of every page</li><li><a href="./reporter.html">Reporter</a> — how each of these objects gets populated</li></ul>',127)])])}const f=t(o,[["render",n]]);export{p as __pageData,f as default};
